UPDATE contents SET body = 'وصلَّى الله على خيرِ البشرِ، الذي أُنْزِلَ عليه: ﴿ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ ﴾ [العنكبوت: ٤٥]، فبيَّن للعباد من فضائل الأذكار، وما فيها من المنافع الكبار، والفوائد ذوات الأخطار، ما ملأ الأسفار، وتناقلته ألسن الرواة في جميع الأقطار، وكان العمل به في جميع الأعصار، وعلى مَن صاحبه ووالاه، وسلَّم تسليمًا كثيرًا لا يُدْرَكُ منتهاه، وبعدُ:', search = 'وصلى الله على خير البشر الذي أنزل عليه ﴿ ولذكۡر ٱلله أكۡبرۗ ﴾ العنكبوت ٤٥ فبين للعباد من فضائل الأذكار وما فيها من المنافع الكبار والفوائد ذوات الأخطار ما ملأ الأسفار وتناقلته ألسن الرواة في جميع الأقطار وكان العمل به في جميع الأعصار وعلى من صاحبه ووالاه وسلم تسليما كثيرا لا يدرك منتهاه وبعد' WHERE id = 1656;
-- p9
UPDATE contents SET source = 'تنبيه: (ص9–10)

حاشية: أمَّا في الألفاظ التي لا يمكن الجمع بينها، بل يتعيَّن اختيارُ أحدها، كصيغ الأذان، والإقامة، والتشهُّد والصلاة على النبي ﷺ، ونحو ذلك، فعليه أن يأتيَ بأحدها مرة، وبأخرى مرةً أخرى.
قال شيخُ الإسلام ابن تيميَّةَ رحمه الله: «الصواب مذهب أهل الحديث، ومن وافقهم، وهو تسويغ كل ما ثبت في ذلك عن النبي ﷺ، لا يكرهون شيئًا من ذلك.
.. ومن تمام السُّنة في مثل هذا: أن يَفعل هذا تارةً، وهذا تارةً، .. لأنَّ هجر ما وردت به السنة، وملازمة غيره، قد يُفضي إلى أن يجعلَ السنة بدعة، والمستحبَّ واجبًا، ويفضي ذلك إلى التفرُّق والاختلاف إذا فعل آخرون الوجه الآخر».اهـ. وانظر: «مجموع الفتاوى» (٢٢/ ٦٦-٧٠)، و«الشرح الممتع» (٣/ ٢٩، ٣٠، ١٦٠).' WHERE id = 1667;
-- p13
UPDATE contents SET body = 'قال الله عز وجل: ﴿ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴾ [الأنفال: ٤٥]', search = 'قال الله عز وجل ﴿ وٱذۡكروا ٱلله كثيرا لعلكمۡ تفۡلحون ﴾ الأنفال ٤٥' WHERE id = 1672;
