UPDATE contents SET body = 'قال الإمام أبو بكر محمد بن الوليد الطُّرْطوشي (ت ٥٢٠هـ) رحمه الله: «ومن العجب العُجاب أن تُعْرِضَ عن الدعوات التي ذكرها الله في كتابه عن الأنبياء، والأولياء، والأصفياء، مقرونةً بالإجابة، ثم تنتقيَ ألفاظَ الشعراء والكُتَّاب كأنَّك قد دعوتَ في زعمِك بجميع دعواتهم، ثم استعنتَ بدعواتِ مَنْ سواهم».اهـ.', search = 'قال الإمام أبو بكر محمد بن الوليد الطرطوشي ت ٥٢٠ه رحمه الله «ومن العجب العجاب أن تعرض عن الدعوات التي ذكرها الله في كتابه عن الأنبياء والأولياء والأصفياء مقرونة بالإجابة ثم تنتقي ألفاظ الشعراء والكتاب كأنك قد دعوت في زعمك بجميع دعواتهم ثم استعنت بدعوات من سواهم» اه' WHERE id = 1698;
