UPDATE contents SET body = 'الباقيات الصالحات -التي وَرَدَ ذِكرُها في قوله تبارك وتعالى: ﴿ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا﴾ [الكهف: ٤٦]، وفي قوله عَزَّ وَجَلَّ: ﴿وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا﴾ [مريم: ٧٦]- هي جميع أعمال الخير، كما جاء عن ابن عبَّاسٍ رضي الله عنهما في قوله: ﴿وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ﴾، قال: «هي ذِكْرُ الله؛ قولُ: لا إله إلا الله، والله أكبرُ، وسبحانَ الله، والحمدُ لله، وتباركَ الله، ولا حول ولا قوَّةَ إلا بالله، وأستغفِرُ الله، وصلَّى اللهُ على رسولِ الله، والصيامُ، والصلاةُ، والحجُّ، والصدقةُ، والعِتْقُ، والجهادُ، والصلةُ، وجميعُ أعمالِ الحسناتِ، وهُنَّ الباقياتُ الصالحاتُ، التي تبقى لأهلها في الجنة ما دامتِ السماواتُ والأرض».', search = 'الباقيات الصالحات -التي ورد ذكرها في قوله تبارك وتعالى ﴿ٱلۡمال وٱلۡبنون زينة ٱلۡحيوة ٱلدنۡياۖ وٱلۡبقيت ٱلصلحت خيۡر عند ربك ثوابا وخيۡر أملا﴾ الكهف ٤٦ وفي قوله عز وجل ﴿ويزيد ٱلله ٱلذين ٱهۡتدوۡا هدىۗ وٱلۡبقيت ٱلصلحت خيۡر عند ربك ثوابا وخيۡر مردا﴾ مريم ٧٦ - هي جميع أعمال الخير كما جاء عن ابن عباس رضي الله عنهما في قوله ﴿وٱلۡبقيت ٱلصلحت﴾ قال «هي ذكر الله قول لا إله إلا الله والله أكبر وسبحان الله والحمد لله وتبارك الله ولا حول ولا قوة إلا بالله وأستغفر الله وصلى الله على رسول الله والصيام والصلاة والحج والصدقة والعتق والجهاد والصلة وجميع أعمال الحسنات وهن الباقيات الصالحات التي تبقى لأهلها في الجنة ما دامت السماوات والأرض»' WHERE id = 1751;
-- p312
UPDATE contents SET body = 'فعن عبد الله بن عمرو رضي الله عنهما قال رسولُ الله ﷺ: «ما على الأرضِ رجلٌ يقول: لا إله إلا الله، والله أكبر، وسبحان الله، والحمدُ لله، ولا حولَ ولا قوَّةَ إلا بالله، إلا كُفِّرَت عَنهُ ذُنُوبُه، ولو كانت أكثرَ مِنْ زَبَدِ البحرِ».', search = 'فعن عبد الله بن عمرو رضي الله عنهما قال رسول الله «ما على الأرض رجل يقول لا إله إلا الله والله أكبر وسبحان الله والحمد لله ولا حول ولا قوة إلا بالله إلا كفرت عنه ذنوبه ولو كانت أكثر من زبد البحر»' WHERE id = 1123;
-- p313
UPDATE contents SET body = 'وعنه رضي الله عنه أنَّ رسولَ الله ﷺ قال: «لَقِيتُ إبراهيمَ ليلةَ أُسرِيَ بي، فقال: يا محمدُ، أقرئْ أُمَّتَك مني السلامَ، وأَخْبِرْهُمْ أنَّ الجنةَ طيبةُ التربةِ، عذبةُ الماءِ، وأنها قِيعانٌ، وأنَّ غِراسَها سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ».', search = 'وعنه رضي الله عنه أن رسول الله قال «لقيت إبراهيم ليلة أسري بي فقال يا محمد أقرئ أمتك مني السلام وأخبرهم أن الجنة طيبة التربة عذبة الماء وأنها قيعان وأن غراسها سبحان الله والحمد لله ولا إله إلا الله والله أكبر»' WHERE id = 1759;
-- p329
UPDATE contents SET source = 'أولًا: في القرآن الكريم. [الفاتحة: ٢]. (ص329)' WHERE id = 1826;
-- p330
UPDATE contents SET source = 'ثانيًا: في السنة الشريفة. (ص330)

حاشية: قال سعيد بن جبير: «إذا قرأتَ: ﴿فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾ [غافر: ١٤]، فقُلْ: «لا إله إلا الله»، وقل على أثرها: «الحمد لله رب العالمين»»، ثم قرأ هذه الآية: ﴿فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ [غافر: ٦٥].' WHERE id = 1835;
-- p336
UPDATE contents SET source = 'معنى التكبير. (ص336)

حاشية: والتفكر المأمور به في خلق الله يمرُّ بثلاث مراحل:
الأولى: أن يستحضرَ المؤمن في قلبه كِبَرَ هذه المخلوقات وعظمتها.
الثانية: أن يستحضرَ عجزَه عن إدراكها والإحاطة بها.
فيتولَّد منهما:
الثالثة: وهي معرفة الخالق سبحانه وتعالى وكبرياءه، وعجز الخلق عن إدراكِ صفاته ونعوت كماله وجلاله وجماله، وهنا يرفع عقيرته مناجيًا ربَّه ومفوِّضًا إليه: «لا أُحصي ثناءً عليك، أنت كما أثنيت على نفسك».' WHERE id = 1855;
-- p337
UPDATE contents SET body = 'فإذا كان نعيمُ أهلِ الجنة -وهي مِن خَلْقِ الله- يعجزُ العقلُ والحواسُّ عن إدراكِهِ مهما حاولَ تخيُّلَه، فما بالُكَ بعظمةِ الخالقِ عَزَّ وَجَلَّ؟', search = 'فإذا كان نعيم أهل الجنة -وهي من خلق الله- يعجز العقل والحواس عن إدراكه مهما حاول تخيله فما بالك بعظمة الخالق عز وجل' WHERE id = 1858;
-- p341
UPDATE contents SET source = 'فضائل الحولقة. (ص341)

حاشية: قال النووي رحمه الله: «ومعنى الكنز هنا أنه ثواب مُدَّخَرٌ في الجنة، وهو ثواب نفيس كما أن الكنز أنفس أموالكم».اهـ. من «شرح النووي»، (١٧/ ٢٦).
وقال ابن حجر رحمه الله: «كنزٌ من كنوز الجنة من حيث إنه يُدَّخَرُ لصاحبها من الثواب ما يقع له في الجنة موقعَ الكنز في الدنيا؛ لأن من شأن الكانز أن يعد كنزه لخلاصه مما ينوبه، والتمتع به فيما يلائمه».اهـ. نقلًا من «الفتوحات الربانية» (١/ ٢٣٨).' WHERE id = 1149;
-- p364
UPDATE contents SET body = 'وتكون الاستعاذة بالله سبحانه كما في قوله تعالى: ﴿ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴾ [النحل: ٩٨]، وكما في حديثِ الوَلِي: «ولَئِن استعاذَ بي لأُعِيذَنَّه».', search = 'وتكون الاستعاذة بالله سبحانه كما في قوله تعالى ﴿ فٱسۡتعذۡ بٱلله من ٱلشيۡطن ٱلرجيم ﴾ النحل ٩٨ وكما في حديث الولي «ولئن استعاذ بي لأعيذنه»' WHERE id = 1951;
-- p370
UPDATE contents SET body = 'عن ابن عابسٍ الجُهَني -وهو عقبة بن عامر- رضي الله عنه أنَّ رسول الله ﷺ قال له: «يا بن عابس، ألا أدُلُّكَ؟» أو قال: «ألا أخبرك بأفضلِ ما يتعوَّذُ به المتعوِّذون؟»، قال: بلى يا رسول الله، قال: «﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾ هاتين السورتين»، وقال له النبيُّ ﷺ: «ما سألَ سائلٌ بمثلهما، ولا استعاذَ مُستعيذٌ بمثلهما».', search = 'عن ابن عابس الجهني -وهو عقبة بن عامر- رضي الله عنه أن رسول الله قال له «يا بن عابس ألا أدلك » أو قال «ألا أخبرك بأفضل ما يتعوذ به المتعوذون » قال بلى يا رسول الله قال «﴿ قلۡ أعوذ برب ٱلۡفلق ﴾ ﴿ قلۡ أعوذ برب ٱلناس ﴾ هاتين السورتين» وقال له النبي «ما سأل سائل بمثلهما ولا استعاذ مستعيذ بمثلهما»' WHERE id = 1977;
-- p383
UPDATE contents SET source = 'الورد الأول. [البقرة: ٢٨٥]. (ص383)' WHERE id = 830;
-- p406
UPDATE contents SET source = 'الورد الرابع. (ص405–406)

حاشية: «ومن شر فتنة الغنى، ومن شر فتنة الفقر»: لأنهما حالتان تُخْشَى الفتنة فيهما بالتسخط وقلة الصبر، والوقوع في حرام أو شبهة للحاجة، ويُخاف في الغنى من الأشر والبَطَرِ، والبخل بحقوق المال، أو إنفاقه في إسراف، أو في باطل، أو في مفاخرة.

حاشية: «بماءِ الثَّلج والبَرَد»: تخصيص الثلج والبَرَد تأكيد للتطهير ومبالغة فيه؛ لأنَّ الثلجَ والبَرَد ماءان مفطوران على خِلقتهما، لم يُستعمَلا ولم تَنَلْهُما الأيدي، ولم تَخُضْهُما الأرجُلُ، كسائر المياه التي قد خالطت تُربة الأرض، وجَرَتْ في الأنهار، واستقرَّتْ في الحياض ونحوها، فكانا أحقَّ بكمال الطهارة، وكذلك هذا المعنى في قوله: «كما نَقَّيتَ الثوبَ الأبيضَ من الدَّنَس» إشباعٌ في بيان التطهير وتأكيدٌ له.' WHERE id = 770;
-- p409
UPDATE contents SET body = 'اللهم اصْرِفْ عني السوءَ والفحشاءَ، واجعلني من عبادِكَ المخلَصين.', search = 'اللهم اصرف عني السوء والفحشاء واجعلني من عبادك المخلصين' WHERE id = 2021;
-- p410
UPDATE contents SET source = 'الورد الخامس. (ص410)

حاشية: أصله أنَّ النبي ﷺ دعا للفتى الذي قال له: «يا رسول الله! ائذن لي بالزنا» الحديث، وفيه أنَّه ﷺ وضَعَ يدَه عليه، وقال: «اللهمَّ اغفر ذنبَه، وطهِّر قلبَه، وحصِّن فرجَه».' WHERE id = 2022;
-- p437
UPDATE contents SET body = 'اللهم مَتِّعْني بسمعي وبصري، واجعلْهُما الوارِثَ مِنِّي، وانْصُرْني على مَن ظلمني، وخُذْ منه بثأري.', search = 'اللهم متعني بسمعي وبصري واجعلهما الوارث مني وانصرني على من ظلمني وخذ منه بثأري' WHERE id = 804;
-- p438
UPDATE contents SET body = 'تَمَّ نورُكَ فهديتَ فلك الحمد، وعَظُمَ حِلْمُكَ فعفوتَ فلك الحمد، وبسطتَ يدَكَ فأعطيتَ فلك الحمد، ربَّنا وجهُكَ أكرمُ الوجوهِ، وجاهُكَ خيرُ الجاهِ، وعَطِيَّتُكَ أفضلُ العَطِيَّة، وأهنؤها، تُطاعُ رَبَّنَا فَتَشْكُرُ، وتُعصَى ربنا فتغفِر، تُجيبُ المضْطَرَّ، وتكشِفُ الضُّرَّ، وتَشْفي السقيمَ، وتُنَجِّي مِنَ الكَرْبِ، وتقبلُ التوبةَ، وتغفر الذنبَ لمن شِئتَ، لا يَجْزِي بآلائك أحدٌ، ولا يُحصِي نَعْماءَكَ قولُ قائل.', search = 'تم نورك فهديت فلك الحمد وعظم حلمك فعفوت فلك الحمد وبسطت يدك فأعطيت فلك الحمد ربنا وجهك أكرم الوجوه وجاهك خير الجاه وعطيتك أفضل العطية وأهنؤها تطاع ربنا فتشكر وتعصى ربنا فتغفر تجيب المضطر وتكشف الضر وتشفي السقيم وتنجي من الكرب وتقبل التوبة وتغفر الذنب لمن شئت لا يجزي بآلائك أحد ولا يحصي نعماءك قول قائل' WHERE id = 2090;

